const j = $input.first().json;
const b = j.body && typeof j.body === 'object' && !Array.isArray(j.body) ? j.body : j;
const prompt = String(b.prompt ?? '');
const klant = String(b.klant ?? 'algemeen');
const openaiKey = ($env.OPENAI_API_KEY || $env.OPTIMUS_API_KEY || '').trim();
const difyAgent = ($env.DIFY_AGENT_API_KEY || '').trim();
if (!openaiKey || !difyAgent) {
  return [{
    json: {
      output: 'Factory OS: zet OPENAI_API_KEY (of OPTIMUS_API_KEY) en DIFY_AGENT_API_KEY in AI_HQ/.env (Factory OS Agent → API Access), daarna docker compose up -d en docker restart n8n.',
      status: 'config_error',
      klant,
      afdeling: 'n/a',
      complexiteit: 'n/a',
    },
  }];
}
return [{ json: { prompt, klant, status: '__ok' } }];

