const raw = $input.first().json;
const prep = $('Prepare').first().json;
const klant = prep.klant || 'algemeen';
const prompt = prep.prompt || '';

if (raw.error) {
  return [{
    json: {
      prompt,
      klant,
      afdeling: 'research',
      complexiteit: 'normaal',
      status: 'ok',
      ceo_fallback: true,
      ceo_error_hint: String(raw.error.message || JSON.stringify(raw.error)).slice(0, 400),
    },
  }];
}

const content = (raw.choices && raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content) || '';
let routing = { afdeling: 'research', complexiteit: 'normaal' };
try {
  const m = content.match(/\{[\s\S]*?\}/);
  if (m) {
    const o = JSON.parse(m[0]);
    if (o.afdeling) routing.afdeling = String(o.afdeling).trim().split(/\s+/)[0];
    if (o.complexiteit) routing.complexiteit = String(o.complexiteit).trim().split(/\s+/)[0];
  }
} catch (e) {}

const afd = (routing.afdeling || 'research').toLowerCase();
const cx = (routing.complexiteit || 'normaal').toLowerCase();
return [{
  json: {
    prompt,
    klant,
    afdeling: afd,
    complexiteit: cx,
    status: 'ok',
  },
}];

